package Practice;

public class Assignment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=100;  //assignment operator '='

		
		a+=10;
		System.out.println("A: "+a); //a=a+10 
		
		a-=10;
		System.out.println("A: "+a); //a=a-10 
		
		a*=10;
		System.out.println("A: "+a); //a=a*10 
		
		a/=10;
		System.out.println("A: "+a); //a=a/10 returns quotient 
		
		a+=10;
		System.out.println("A: "+a); //a=a%10 returns remainder 
		
	}

}
